/**
 * Presentation helpers for browser-handoff connector actions
 * (e.g. LinkedIn prepare_comment / verify_staged_comment).
 *
 * Keeps ActionApprovalCard free of stringly shape checks.
 */

function asString(value: unknown): string | undefined {
	if (typeof value !== "string") return undefined;
	const t = value.trim();
	return t.length > 0 ? t : undefined;
}

function asBool(value: unknown): boolean | undefined {
	return typeof value === "boolean" ? value : undefined;
}

export type BrowserHandoffSummary = {
	kind: "prepare" | "verify" | "generic";
	/** Human-facing status line (output.message or verify outcome). */
	message?: string;
	/** Why this was proposed / staged (input.reason or output.reason_preview). */
	reason?: string;
	/** Draft body for prepare, or expected body for verify. */
	body?: string;
	postUrl?: string;
	prepared?: boolean;
	bannerShown?: boolean;
	verified?: boolean;
	matchPreview?: string;
	matchAuthor?: string;
	/** Short chips shown under the title. */
	chips: string[];
};

/**
 * True when input/output look like a browser handoff (stage for human, or verify).
 */
export function isBrowserHandoffShape(
	input: Record<string, unknown> | null | undefined,
	output: Record<string, unknown> | null | undefined,
	actionKey?: string | null,
): boolean {
	const key = (actionKey ?? "").toLowerCase();
	if (
		key === "prepare_comment" ||
		key === "verify_staged_comment" ||
		key.includes("prepare_") ||
		key.includes("verify_staged")
	) {
		return true;
	}
	if (output?.prepared === true) return true;
	if (typeof output?.verified === "boolean") return true;
	if (asString(output?.reason_preview) && asString(output?.message)) return true;
	// Pending prepare: body + (post_url|activity_id) + optional reason.
	if (
		asString(input?.body) &&
		(asString(input?.post_url) || asString(input?.activity_id))
	) {
		return true;
	}
	return false;
}

export function buildBrowserHandoffSummary(
	input: Record<string, unknown> | null | undefined,
	output: Record<string, unknown> | null | undefined,
	actionKey?: string | null,
): BrowserHandoffSummary | null {
	if (!isBrowserHandoffShape(input, output, actionKey)) return null;

	const key = (actionKey ?? "").toLowerCase();
	const body = asString(output?.body) ?? asString(input?.body);
	const reason =
		asString(output?.reason_preview) ?? asString(input?.reason);
	const postUrl =
		asString(output?.post_url) ??
		asString(input?.post_url) ??
		(asString(input?.activity_id)
			? `https://www.linkedin.com/feed/update/urn:li:activity:${asString(input?.activity_id)}`
			: undefined);
	const prepared = asBool(output?.prepared);
	const verified = asBool(output?.verified);
	const bannerShown = asBool(output?.banner_shown);
	const message = asString(output?.message);

	const match =
		output?.match && typeof output.match === "object"
			? (output.match as Record<string, unknown>)
			: null;
	const matchPreview = asString(match?.text_preview);
	const matchAuthor = asString(match?.author);

	let kind: BrowserHandoffSummary["kind"] = "generic";
	if (
		key === "verify_staged_comment" ||
		key.includes("verify") ||
		typeof verified === "boolean"
	) {
		kind = "verify";
	} else if (
		key === "prepare_comment" ||
		key.includes("prepare") ||
		prepared === true ||
		// pending prepare
		(!!body && !!postUrl)
	) {
		kind = "prepare";
	}

	const chips: string[] = [];
	if (prepared === true) chips.push("Staged — not posted");
	if (prepared === false) chips.push("Not staged");
	if (verified === true) chips.push("Verified posted");
	if (verified === false) chips.push("Not verified as posted");
	if (bannerShown === true) chips.push("In-page banner");
	if (bannerShown === false) chips.push("No banner");

	return {
		kind,
		message,
		reason,
		body,
		postUrl,
		prepared,
		bannerShown,
		verified,
		matchPreview,
		matchAuthor,
		chips,
	};
}
