	body: "Great insight — thanks for sharing.",
	reason: "Met at conference",
	post_url:
		"https://www.linkedin.com/feed/update/urn:li:activity:7481350304106528768",
	focus: true,
	banner: true,
};

const prepareOutput = {
	prepared: true,
	banner_shown: true,
	reason_preview: "Met at conference",
	body: "Great insight — thanks for sharing.",
	post_url:
		"https://www.linkedin.com/feed/update/urn:li:activity:7481350304106528768",
	message:
		"Comment staged in your browser. Review the draft and click Post yourself — Lobu did not submit.",
	method: "evaluate",
	tab_id: 42,
};

describe("isBrowserHandoffShape", () => {
	it("detects prepare_comment by key and by prepared output", () => {
		expect(isBrowserHandoffShape(prepareInput, null, "prepare_comment")).toBe(
			true,
		);
		expect(isBrowserHandoffShape({}, prepareOutput, null)).toBe(true);
		expect(isBrowserHandoffShape({ foo: 1 }, { bar: 2 }, "send_email")).toBe(
			false,
		);
	});
});

describe("buildBrowserHandoffSummary", () => {
	it("surfaces reason, body, message, and staged chips for prepare output", () => {
		const s = buildBrowserHandoffSummary(
			prepareInput,
			prepareOutput,
			"prepare_comment",
		);
		expect(s).toMatchObject({
			kind: "prepare",
			reason: "Met at conference",
			body: "Great insight — thanks for sharing.",
			message: prepareOutput.message,
			prepared: true,
			bannerShown: true,
		});
		expect(s?.chips).toContain("Staged — not posted");
		expect(s?.chips).toContain("In-page banner");
	});

	it("shows reason from input while pending (no output yet)", () => {
		const s = buildBrowserHandoffSummary(prepareInput, null, "prepare_comment");
		expect(s?.reason).toBe("Met at conference");
		expect(s?.body).toBe(prepareInput.body);
		expect(s?.message).toBeUndefined();
		expect(s?.prepared).toBeUndefined();
	});

	it("summarizes verify results", () => {
		const s = buildBrowserHandoffSummary(
			{ body: "hello world draft text here", post_url: "https://x" },
			{
				verified: false,
				reason: "no_matching_comment",
				message: "Comments are visible but none matched.",
				body: "hello world draft text here",
			},
			"verify_staged_comment",
		);
		expect(s?.kind).toBe("verify");
		expect(s?.verified).toBe(false);
		expect(s?.chips).toContain("Not verified as posted");
		expect(s?.message).toMatch(/none matched/i);
	});
});
