function shortText(value, fallback, maxLen) {
	const text = typeof value === "string" ? value.trim() : "";
	return (text || fallback).slice(0, maxLen);
}

async function readNotificationTargets(chromeApi) {
	const stored = await chromeApi.storage.local.get(NOTIFICATION_TARGETS_KEY);
	const value = stored[NOTIFICATION_TARGETS_KEY];
	return value && typeof value === "object" ? value : {};
}

async function writeNotificationTargets(chromeApi, targets) {
	await chromeApi.storage.local.set({ [NOTIFICATION_TARGETS_KEY]: targets });
}

function normalizeClickUrl(value) {
	if (typeof value !== "string" || !value.trim()) return null;
	try {
		const url = new URL(value.trim());
		return url.protocol === "http:" || url.protocol === "https:"
			? url.toString()
			: null;
	} catch {
		return null;
	}
}

async function storeNotificationTarget(chromeApi, notificationId, args) {
	const tabId = typeof args?.tab_id === "number" ? args.tab_id : null;
	const clickUrl = normalizeClickUrl(
		args?.click_url ?? args?.url ?? args?.landed_url,
	);
	if (tabId == null && !clickUrl) return;
	const targets = await readNotificationTargets(chromeApi);
	targets[notificationId] = {
		tab_id: tabId,
		click_url: clickUrl,
		stored_at: Date.now(),
	};
	await writeNotificationTargets(chromeApi, targets);
}

export async function handleNotificationClick(chromeApi, notificationId) {
	const targets = await readNotificationTargets(chromeApi);
	const target = targets[notificationId];
	delete targets[notificationId];
