/**
 * Path reservation + system-type hide helpers from `@lobu/core/reserved`.
 *
 * IMPORTANT: import the `./reserved` subpath, never the `@lobu/core` barrel.
 * The barrel re-exports logger/otel/sentry (Node-only, top-level `process.env`).
 * Rollup cannot tree-shake those through CJS `__exportStar`, so a barrel import
 * ships `process` into the SPA and crashes prod with
 * `Uncaught ReferenceError: process is not defined`.
 */
import { decodeEntityTypeParam } from "@/lib/url";
import {
	isSystemEntityType,
	OWNER_ROUTE_SEGMENTS,
	REMOVED_OWNER_SEGMENTS,
	RESERVED_PATHS,
	RESERVED_PATHS_SET,
} from "@lobu/core/reserved";

export { isSystemEntityType, RESERVED_PATHS, RESERVED_PATHS_SET };

/** Owner-level + removed legacy pages only (not global prefixes like auth/api). */
const RESERVED_OWNER_SEGMENTS_SET = new Set<string>([
	...OWNER_ROUTE_SEGMENTS,
	...REMOVED_OWNER_SEGMENTS,
]);

/**
 * True when a URL segment must not be treated as a user-defined entity type
 * (owner-level routes and removed legacy pages).
 */
export function isReservedOwnerSegment(segment: string): boolean {
	return RESERVED_OWNER_SEGMENTS_SET.has(decodeEntityTypeParam(segment));
}
import { describe, expect, it } from "vitest";
import {
	isSystemEntityType,
	isReservedOwnerSegment,
	RESERVED_PATHS,
} from "@/lib/reserved";

describe("isReservedOwnerSegment", () => {
	it("rejects owner-level route segments", () => {
		for (const segment of ["memory", "agents", "connectors", "devices"]) {
			expect(isReservedOwnerSegment(segment)).toBe(true);
		}
	});

	it("rejects removed legacy owner pages", () => {
		for (const segment of [
			"events",
			"sources",
			"connections",
			"behaviors",
			"environments",
			"infrastructure",
			"inference-providers",
		]) {
			expect(isReservedOwnerSegment(segment)).toBe(true);
		}
	});

	it("allows global route prefixes that may be valid entity type slugs", () => {
		expect(isReservedOwnerSegment("auth")).toBe(false);
		expect(isReservedOwnerSegment("api")).toBe(false);
		expect(isReservedOwnerSegment("templates")).toBe(false);
	});

	it("allows encoded system entity types", () => {
		expect(isReservedOwnerSegment("%24member")).toBe(false);
		expect(isReservedOwnerSegment("test-vendor")).toBe(false);
	});

	it("keeps RESERVED_PATHS as the broader org-slug guard superset", () => {
		expect(RESERVED_PATHS).toContain("memory");
		expect(RESERVED_PATHS).toContain("auth");
		expect(RESERVED_PATHS).toContain("connections");
	});
});

describe("isSystemEntityType", () => {
	it("is solely the $ slug prefix", () => {
		expect(isSystemEntityType({ slug: "$member" })).toBe(true);
		expect(isSystemEntityType({ slug: "$resource" })).toBe(true);
		expect(isSystemEntityType({ slug: "person" })).toBe(false);
		expect(isSystemEntityType({ slug: "channel" })).toBe(false);
		expect(isSystemEntityType({})).toBe(false);
	});
});
