export interface TestUser {
  id: string;
  email: string;
  name: string;
  username: string;
}

interface TestAgent {
  agentId: string;
  organizationId: string;
  name: string;
}

export async function createTestUser(options?: {
  email?: string;
  name?: string;
  username?: string;
}): Promise<TestUser> {
  const sql = getTestDb();
  const id = `user_${generateSecureToken(8)}`;
  const email = options?.email || `${id.slice(5, 13)}@test.example.com`;
  const name = options?.name || `Test User ${id.slice(5, 13)}`;
  const baseUsername =
    options?.username ||
    email
      .split('@')[0]
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '-')
      .replace(/^-+|-+$/g, '');
  const username =
    baseUsername.length > 0 ? `${baseUsername}-${id.slice(5, 9)}` : `user-${id.slice(5, 9)}`;

  await sql`
    INSERT INTO "user" (id, email, name, username, "emailVerified", "createdAt", "updatedAt")
    VALUES (${id}, ${email}, ${name}, ${username}, true, NOW(), NOW())
  `;

  return { id, email, name, username };
}

export async function addUserToOrganization(
  userId: string,
  organizationId: string,
  role: string = 'member'
): Promise<string> {
  const sql = getTestDb();
  const memberId = `member_${generateSecureToken(8)}`;

  await sql`
    INSERT INTO "member" (id, "userId", "organizationId", role, "createdAt")
    VALUES (${memberId}, ${userId}, ${organizationId}, ${role}, NOW())
  `;

  return memberId;
}

/**
 * A `ToolContext` for an org owner with full MCP scopes — the shape connector
 * admin-tool tests need to call `manageConnections` / `manageFeeds` as the
 * connection owner.
 */
export function ownerToolContext(organizationId: string, userId: string): ToolContext {
  return {
    organizationId,
    userId,
    memberRole: 'owner',
    agentId: null,
    isAuthenticated: true,
    clientId: null,
    scopes: ['mcp:read', 'mcp:write', 'mcp:admin'],
    tokenType: 'oauth',
    scopedToOrg: true,
    allowCrossOrg: false,
  } as ToolContext;
}

/**
 * Seed an org with `user` as owner, returning both plus a ready owner
 * `ToolContext`. Collapses the org + user + membership + context boilerplate
 * that connector admin-tool tests otherwise repeat per case.
	watcherId: number,
	organizationId: string,
): Promise<{ ownerAgentId: string | null; resolved: boolean }> {
	// INNER JOIN agents: the row resolves ONLY when the owning agent still exists in
	// this org. A dangling agent_id (agent deleted mid-flight) yields zero rows →
	// resolved:false → gates deny, closing the fail-open where a deleted agent's
	// watcher would fall back to the looser org default.
	const rows = await sql<{ agent_id: string }>`
    SELECT w.agent_id
    FROM watchers w
    JOIN agents a ON a.id = w.agent_id AND a.organization_id = ${organizationId}
    WHERE w.id = ${watcherId} AND w.organization_id = ${organizationId}
    LIMIT 1
  `;
	if (rows.length === 0) return { ownerAgentId: null, resolved: false };
	return { ownerAgentId: rows[0].agent_id, resolved: true };
}

/** The fully-resolved acting principal for one write, ready to hand to the gate. */
export interface ActingPrincipal {
	kind: EntityPolicyPrincipalKind;
	/** `watcher:<id>` / agent id / null ("any of this kind"). */
	id: string | null;
	/** The watcher's owning agent, folded max-restrictive; null unless a watcher. */
	ownerAgentId: string | null;
	/**
	 * False ONLY when this is a watcher whose owning-agent lookup FAILED (the watcher
	 * row is gone). The gate must FAIL CLOSED (deny) rather than run the write as an
	 * unowned watcher against the looser org default — otherwise a reaction whose
	 * watcher was hard-deleted mid-flight escapes its agent's envelope. True for every
	 * agent/user turn and every watcher whose owner resolved (incl. legitimately null).
	 */
	ownerResolved: boolean;
}

