export async function handleUninstallConnector(
	args: Extract<ConnectionsArgs, { action: "uninstall_connector" }>,
	ctx: ToolContext,
): Promise<ManageConnectionsResult> {
	try {
		const archived = await uninstallConnectorDefinition({
			organizationId: ctx.organizationId,
			connectorKey: args.connector_key,
		});
		if (!archived) {
			return {
				error: `Connector '${args.connector_key}' not found or already archived`,
			};
		}
	} catch (error) {
		return { error: getErrorMessage(error) };
	}

	recordToolConfigChange(ctx, {
		resourceKind: "connector-definition",
		resourceId: args.connector_key,
		op: "deleted",
		summary: `Connector '${args.connector_key}' uninstalled`,
		const scopes = Array.isArray(a.requiredScopes)
			? (a.requiredScopes.filter((s) => typeof s === "string") as string[])
			: [];
		out[key] = {
			// Reuse the exact runtime classifier so the preflight can't disagree
			// with how the action is actually treated (kind:'read' OR
			// annotations.readOnlyHint:true → read; else write).
			kind: getLocalActionKind(a),
			requires_approval: a.requiresApproval === true,
			required_scopes: scopes,
		};
	}
	return out;
}

